[1, 1, 2, 3, 3, 3, 3, 4, 4, 4].mode() // returns 3
let emptyArray: [Int] = []
emptyArray.mode() // returns nil

func mode() -> Element? {
    var frequencies = [Element: Int]()

    // Standard for loop. Can also use the forEach(_:) or reduce(into:) methods on self.
    for element in self {
        frequencies[element] = (frequencies[element] ?? 0) + 1
    }

    // The max(by:) method used here to find one of the elements with the highest associated count.
    if let ( mode, _ ) = frequencies.max(by: { $0.value < $1.value }) {
        return mode
    } else {
        return nil
    }
}

struct SimpleMovingAverage {
  var period: Int
  var numbers = [Double]()
}
for period in [3, 5] {
  print("Moving average with period \(period)")
  var averager = SimpleMovingAverage(period: period)
  for n in [1.0, 2, 3, 4, 5, 5, 4, 3, 2, 1] {
    print("n: \(n); average \(averager.addNumber(n))")
  }
}

mutating func addNumber(_ n: Double) -> Double {
  numbers.append(n)

  if numbers.count > period {
    numbers.removeFirst()
  }

  guard !numbers.isEmpty else {
    return 0
  }

  return numbers.reduce(0, +) / Double(numbers.count)
}

