func modPow(exp: Self, mod: Self) -> Self {
  guard exp != 0 else {
    return 1
  }

  var res = Self(1)
  var base = self % mod
  var exp = exp

  while true {
    if exp & 1 == 1 {
      res *= base
      res %= mod
    }

    if exp == 1 {
      return res
    }

    exp >>= 1
    base *= base
    base %= mod
  }
}

func mFactor(exp: Int) -> Int? {
  for k in 0..<16384 {
    let q = 2*exp*k + 1

    if !q.isPrime {
      continue
    } else if q % 8 != 1 && q % 8 != 7 {
      continue
    } else if 2.modPow(exp: exp, mod: q) == 1 {
      return q
    }
  }

  return nil
}

class Farey {
    let n: Int
    init(_ x: Int) {
        n = x
    }
    var sequence: [(Int,Int)] {
        var a = 0
        var b = 1
        var c = 1
        var d = n
        var results = [(a, b)]
        while c <= n {
            let k = (n + b) / d
            let oldA = a
            let oldB = b
            a = c
            b = d
            c = k * c - oldA
            d = k * d - oldB
            results += [(a, b)]
        }
        return results
    }
    var formattedSequence: String {
        var s = "\(n):"
        for pair in sequence {
            s += " \(pair.0)/\(pair.1)"
        }
        return s
    }
}
