func lastSundays(of year: Int) -> [Date] {

	let calendar = Calendar.current
	var dates = [Date]()

	for month in 1...12 {

		var dateComponents = DateComponents(calendar: calendar,
		                                    year: year,
		                                    month: month + 1,
		                                    day: 0,
		                                    hour: 12)

		let date = calendar.date(from: dateComponents)!
		let weekday = calendar.component(.weekday, from: date)

		if weekday != 1 {
			dateComponents.day! -= weekday - 1
		}

		dates.append(calendar.date(from: dateComponents)!)
	}
	return dates
}

func p2(L: Int, n: Int) -> Int {
  let asString = String(L)
  var digits = 1

  for _ in 1...18-asString.count {
    digits *= 10
  }

  let ten18 = Int(1e18)

  var count = 0, i = 0, probe = 1

  while true {
    probe += probe
    i += 1

    if probe >= ten18 {
      while true {
        if probe >= ten18 {
          probe /= 10
        }

        if probe / digits == L {
          count += 1

          if count >= n {
            count -= 1
            break
          }
        }

        probe += probe
        i += 1
      }
    }

    let probeString = String(probe)
    var len = asString.count

    if asString.count > probeString.count {
      len = probeString.count
    }

    if probeString.prefix(len) == asString {
      count += 1

      if count >= n {
        break
      }
    }
  }

  return i
}

