                    if player == wumpus {
                        print("You have been eaten by the wumpus and lost the game!")
                        return
                    }
                }
            }
            //reduce arrow after shoot
            arrows-=1
            if arrows == 0 {
                print("You have run out of arrows and lost the game!")
                return
            }
        }
    }
}

