public mutating func next() -> Int? {
  while i < n {
    defer { i += 1 }

    if sieve[i] != 0 {
      if i <= limit {
        for notPrime in stride(from: i * i, through: n, by: i) {
          sieve[notPrime] = 0
        }
      }

      return i
    }
  }

  return nil
}

func findPeriod(n: Int) -> Int {
  let r = (1...n+1).reduce(1, {res, _ in (10 * res) % n })
  var rr = r
  var period = 0

  repeat {
    rr = (10 * rr) % n
    period += 1
  } while r != rr

  return period
}

