func isPrime(_ n: Int) -> Bool {
    if n < 2 {
        return false
    }
    if n % 2 == 0 {
        return n == 2
    }
    if n % 3 == 0 {
        return n == 3
    }
    var p = 5
    while p * p <= n {
        if n % p == 0 {
            return false
        }
        p += 2
        if n % p == 0 {
            return false
        }
        p += 4
    }
    return true
}

func isMagnanimous(_ n: Int) -> Bool {
    var p = 10;
    while n >= p {
        if !isPrime(n % p + n / p) {
            return false
        }
        p *= 10
    }
    return true
}

func A(_ k: Int,
       _ x1: @escaping () -> Int,
       _ x2: @escaping () -> Int,
       _ x3: @escaping () -> Int,
       _ x4: @escaping () -> Int,
       _ x5: @escaping () -> Int) -> Int {
    var k1 = k

    func B() -> Int {
        k1 -= 1
        return A(k1, B, x1, x2, x3, x4)
    }

    if k1 <= 0 {
        return x4() + x5()
    } else {
        return B()
    }
}

