    return ModInt((lhs.value + rhs.value) % lhs.modulo, modulo: lhs.modulo)
  }
  static func *(lhs: ModInt, rhs: ModInt) -> ModInt {
    precondition(lhs.modulo == rhs.modulo)
    return ModInt((lhs.value * rhs.value) % lhs.modulo, modulo: lhs.modulo)
  }
