func threeDigitsToText(n: Int) -> String {
  guard n != 0 else {
    return ""
  }

  var ret = ""

  let hundreds = n / 100
  let remainder = n % 100

  if hundreds > 0 {
    ret += "\(Int.names[hundreds]!) hundred"

    if remainder > 0 {
      ret += " "
    }
  }

  if remainder > 0 {
    let tens = remainder / 10
    let units = remainder % 10

    if tens > 1 {
      ret += Int.names[tens * 10]!

      if units > 0 {
        ret += "-\(Int.names[units]!)"
      }
    } else {
      ret += Int.names[remainder]!
    }
  }

  return ret
}

