public func totient(n: Int) -> Int {
  var n = n
  var i = 2
  var tot = n

  while i * i <= n {
    if n % i == 0 {
      while n % i == 0 {
        n /= i
      }

      tot -= tot / i
    }

    if i == 2 {
      i = 1
    }

    i += 2
  }

  if n > 1 {
    tot -= tot / n
  }

  return tot
}

public mutating func next() -> Int? {
  while true {
    defer {
      m += 1
    }

    var tot = m
    var sum = 0

    while tot != 1 {
      tot = totient(n: tot)
      sum += tot
    }

    if sum == m {
      return m
    }
  }
}

private static func grad(_ hash: Int, _ x: Double, _ y: Double, _ z: Double) -> Double {
  let h = hash & 15
  let u = h < 8 ? x : y
  let v = h < 4 ? y : h == 12 || h == 14 ? x : z

  return (h & 1 == 0 ? u : -u) + (h & 2 == 0 ? v : -v)
}

static func noise(x: Double, y: Double, z: Double) -> Double {
  let xi = Int(x) & 255
  let yi = Int(y) & 255
  let zi = Int(z) & 255

  let xx = x - floor(x)
  let yy = y - floor(y)
  let zz = z - floor(z)

  let u = fade(xx)
  let v = fade(yy)
  let w = fade(zz)

  let a  = p[xi] + yi
  let aa = p[a] + zi
  let b  = p[xi + 1] + yi
  let ba = p[b] + zi
  let ab = p[a + 1] + zi
  let bb = p[b + 1] + zi

  return lerp(w, lerp(v, lerp(u, grad(p[aa], xx, yy, zz),
    grad(p[ba], xx - 1, yy, zz)),
    lerp(u, grad(p[ab], xx, yy - 1, zz),
      grad(p[bb], xx - 1, yy - 1, zz))),
    lerp(v, lerp(u, grad(p[aa + 1], xx, yy, zz - 1),
      grad(p[ba + 1], xx - 1, yy, zz - 1)),
      lerp(u, grad(p[ab + 1], xx, yy - 1, zz - 1),
        grad(p[bb + 1], xx - 1, yy - 1, zz - 1))))
}

func generate<T>(array: inout [T], output: (_: [T], _: Int) -> Void) {
    let n = array.count
    var c = Array(repeating: 0, count: n)
    var i = 1
    var sign = 1
    output(array, sign)
    while i < n {
        if c[i] < i {
            if (i & 1) == 0 {
                array.swapAt(0, i)
            } else {
                array.swapAt(c[i], i)
            }
            sign = -sign
            output(array, sign)
            c[i] += 1
            i = 1
        } else {
            c[i] = 0
            i += 1
        }
    }
}

