mutating func next() -> T? {
  let curll = self._current
  if (self._isfirst) { self._isfirst = false; return curll.head }
  let ncur = curll.tail
  if (ncur == nil) { return nil }
  self._current = ncur!
  return ncur!.head
}

func makeIterator() -> LLSeqIter {
  return LLSeqIter(self._current)
}

