public func cocktailSorted() -> [Element] {
  var swapped = false
  var ret = Array(self)

  guard count > 1 else {
    return ret
  }

  repeat {
    for i in 0...ret.count-2 where ret[i] > ret[i + 1] {
      (ret[i], ret[i + 1]) = (ret[i + 1], ret[i])
      swapped = true
    }

    guard swapped else {
      break
    }

    swapped = false

    for i in stride(from: ret.count - 2, through: 0, by: -1) where ret[i] > ret[i + 1] {
      (ret[i], ret[i + 1]) = (ret[i + 1], ret[i])
      swapped = true
    }
  } while swapped

  return ret
}

func cocktailShakerSort<T: Comparable>(_ a: inout [T]) {
    var begin = 0
    var end = a.count
    if end == 0 {
        return
    }
    end -= 1
    while begin < end {
        var new_begin = end
        var new_end = begin
        var i = begin
        while i < end {
            if a[i + 1] < a[i] {
                a.swapAt(i, i + 1)
                new_end = i
            }
            i += 1
        }
        end = new_end
        i = end
        while i > begin {
            if a[i] < a[i - 1] {
                a.swapAt(i, i - 1)
                new_begin = i
            }
            i -= 1
        }
        begin = new_begin
    }
}

func gnomeSort<T: Comparable>(_ a: inout [T]) {
    var i = 1
    var j = 2
    while i < a.count {
        if a[i - 1] <= a[i] {
            i = j
            j += 1
        } else {
            a.swapAt(i - 1, i)
            i -= 1
            if i == 0 {
                i = j
                j += 1
            }
        }
    }
}

func mergeSort(_ array: [Int]) -> [Int] {
  guard array.count > 1 else { return array }

  let middleIndex = array.count / 2

  let leftPart = mergeSort(Array(array[0..<middleIndex]))
  let rightPart = mergeSort(Array(array[middleIndex..<array.count]))

  func merge(left: [Int], right: [Int]) -> [Int] {
    var leftIndex = 0
    var rightIndex = 0

    var merged = [Int]()
    merged.reserveCapacity(left.count + right.count)

    while leftIndex < left.count && rightIndex < right.count {
      if left[leftIndex] < right[rightIndex] {
        merged.append(left[leftIndex])
        leftIndex += 1
      } else if left[leftIndex] > right[rightIndex] {
        merged.append(right[rightIndex])
        rightIndex += 1
      } else {
        merged.append(left[leftIndex])
        leftIndex += 1
        merged.append(right[rightIndex])
        rightIndex += 1
      }
    }

    while leftIndex < left.count {
      merged.append(left[leftIndex])
      leftIndex += 1
    }

    while rightIndex < right.count {
      merged.append(right[rightIndex])
      rightIndex += 1
    }

    return merged
  }

  return merge(left: leftPart, right: rightPart)
}

