func levelOrder(function: (T) -> Void) {
    var queue: [TreeNode] = []
    queue.append(self)
    while queue.count > 0 {
        let node = queue.removeFirst()
        function(node.value)
        if node.left != nil {
            queue.append(node.left!)
        }
        if node.right != nil {
            queue.append(node.right!)
        }
    }
}

