mutating func next() -> Int? {
    let result = lastTerm
    var nextTerm = 0
    if let v = lastPos[lastTerm] {
        nextTerm = index - v
    }
    lastPos[lastTerm] = index
    lastTerm = nextTerm
    index += 1
    return result
}

